149	  @keyframes pulse-dot {
150	    0%, 100% { box-shadow: 0 0 0 0 rgb(52 211 153 / 0.5); }
151	    50% { box-shadow: 0 0 0 5px rgb(52 211 153 / 0); }
152	  }
153	  /* One-shot bar grow (origin at the base). Resting state = full. */
154	  @keyframes grow-up {
155	    from { transform: scaleY(0.06); }
156	    to { transform: scaleY(1); }
157	  }
158	  /* One-shot progress/usage fill. Resting state = full width. */
159	  @keyframes grow-x {
160	    from { transform: scaleX(0); }
161	    to { transform: scaleX(1); }
162	  }
163	  /* Continuous "live traffic" equaliser pulse. Resting state = full height. */
164	  @keyframes eq {
165	    0%, 100% { transform: scaleY(0.35); }
166	    50% { transform: scaleY(1); }
167	  }
168	  /* Terminal cursor blink. Resting state = visible. */
169	  @keyframes blink {
170	    0%, 49% { opacity: 1; }
171	    50%, 100% { opacity: 0; }
172	  }
173	  /* Soft light sweep across a chart/highlight. */
174	  @keyframes sweep {
175	    0% { transform: translateX(-120%); opacity: 0; }
176	    40%, 60% { opacity: 0.7; }
177	    100% { transform: translateX(320%); opacity: 0; }
178	  }
179	  /* Staggered line/row reveal. Resting state = visible. */
180	  @keyframes line-in {
181	    from { opacity: 0; transform: translateY(6px); }
182	    to { opacity: 1; transform: translateY(0); }
183	  }
184	
185	  /* Post-payment provisioning/success screen (ProvisioningOverlay). All
186	     opt-in via `motion-safe:`, so reduced-motion users see the resting frame
187	     (full ring / checkmark drawn / settled position) with no motion. */
188	  --animate-orbit-spin: orbit-spin 1.4s linear infinite;
189	  --animate-check-pop: check-pop 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
190	  --animate-check-draw: check-draw 0.4s 0.2s ease-out both;
191	  --animate-ring-glow: ring-glow 2.4s ease-in-out infinite;
192	
193	  /* Continuous loader ring — a single arc rotating around the icon. Resting
194	     state = arc visible at its start position (no motion). */
195	  @keyframes orbit-spin {
196	    from { transform: rotate(0deg); }
197	    to { transform: rotate(360deg); }
198	  }
199	  /* Success badge pop-in (runs once the icon swaps from spinner to check). */
200	  @keyframes check-pop {
201	    0% { opacity: 0; transform: scale(0.5); }
202	    70% { transform: scale(1.08); }
203	    100% { opacity: 1; transform: scale(1); }
204	  }
205	  /* Checkmark stroke draw, timed to start just after check-pop settles. */
206	  @keyframes check-draw {
207	    from { stroke-dashoffset: 24; }
208	    to { stroke-dashoffset: 0; }
209	  }
210	  /* Slow ambient glow behind the provisioning icon. Resting state = mid-glow. */
211	  @keyframes ring-glow {
212	    0%, 100% { opacity: 0.5; }
213	    50% { opacity: 1; }
214	  }
215	}
