217	/* ══ NEXION PALETTE, SCOPED TO THE PORTAL ════════════════════════════════════
218	   The dashboard's actual colors, reusing production's own slot names
219	   (brand-*, navy-*, accent-*, slate-*) so the ~4,700 existing `bg-brand-500`/
220	   `text-slate-300`/etc. usages inside the portal resolve to Nexion's palette
221	   — but scoped to `.nx-shell-root` (components/nx/Shell.tsx's own root
222	   element, present on every /dashboard page and nowhere else) instead of the
223	   bare `@theme` above, so marketing/login/admin keep production's original
224	   colors regardless of what the portal's palette does. Same technique
225	   `.nx-dark-island` already uses for the rail/header, one level up: this is
226	   effectively "the whole portal is one dark island with its own tokens."
227	
228	   Ground rules carried over from the design canvas:
229	     - the page ground is DARKER than the cards (navy-950 < navy-900)
230	     - rims are zero-red blues; a periwinkle rim reads cheap at this saturation
231	     - accents sit deliberately off full saturation (pulled 14-24 points)
232	
233	   Scoped to `:root:has(.nx-shell-root)`, not `.nx-shell-root` directly: several
234	   dashboard surfaces (CardSetupModal, AddFundsPaymentModal, SettleBalanceModal,
235	   the command palette, toasts) `createPortal` to `document.body` — a DIRECT
236	   CHILD of `<html>`, a DOM SIBLING of `.nx-shell-root`, not a descendant of it.
237	   Custom properties cascade through the real DOM tree, not the React tree, so
238	   scoping to the class itself would leave every portaled modal reading
239	   production's reverted colors instead of Nexion's the moment it opened.
240	   `:has()` re-evaluates on `<html>` (an ancestor of both `.nx-shell-root` and
241	   anything portaled to body) purely from whether a `.nx-shell-root` exists
242	   ANYWHERE in the document, so it covers portals automatically and needs no
243	   JS to stay correct across a client-side enter/exit of the dashboard either. */
244	:root:has(.nx-shell-root) {
245	  /* brand ramp — Nexion violet #8c3ae9 at the 500 stop */
246	  --color-brand-50: #f4ecfe;
247	  --color-brand-100: #e6d4fb;
248	  --color-brand-200: #cfaef7;
249	  --color-brand-300: #b785f2;
250	  --color-brand-400: #a05cf0;
251	  --color-brand-500: #8c3ae9;
252	  --color-brand-600: #7a2fd0;
253	  --color-brand-700: #6626ad;
254	  --color-brand-800: #52208a;
255	  --color-brand-900: #421c6e;
256	
257	  /* surfaces — 950 is the page ground and is the DARKEST; cards step up */
258	  --color-navy-950: #000816;
259	  --color-navy-900: #010f22;
260	  --color-navy-850: #021428;
261	  --color-navy-800: #00152f;
262	  --color-navy-700: #002049;
263	  --color-navy-600: #002a5e;
264	
265	  --color-accent-blue: #2f7eef;
266	  --color-accent-cyan: #14c5e4;
267	
268	  /* text ramp — overrides Tailwind's stock slate INSIDE the portal only.
269	     Nexion's text is blue-tinted, not neutral grey. */
270	  --color-slate-50: #ffffff;
271	  --color-slate-100: #eaf2ff;
272	  --color-slate-200: #d8e6ff;
273	  --color-slate-300: #cbdcff;
274	  --color-slate-400: #93aede;
275	  --color-slate-500: #7f9ad0;
276	  --color-slate-600: #5f7cb4;
277	  --color-slate-700: #2b4a80;
278	  --color-slate-800: #001a3d;
279	  --color-slate-900: #00102a;
280	  --color-slate-950: #000816;
