325	  --color-rim: #d3dfef;
326	  --color-rim-soft: #e3eaf5;
327	  --color-rim-hi: #bfd0e7;
328	
329	  /* Accents pulled a little darker so they hold contrast on white. */
330	  --color-brand-500: #7a2fd0;
331	  --color-brand-400: #8c3ae9;
332	  --color-brand-300: #7a2fd0;
333	  --color-accent-blue: #1f63cc;
334	  --color-accent-cyan: #0b91ab;
335	  --color-cyan: #0b91ab;
336	  --color-blue: #1f63cc;
337	  --color-violet: #7a2fd0;
338	  --color-magenta: #b3159c;
339	  --color-mint: #0a9c6f;
340	  --color-amber: #b97708;
341	  --color-rose: #d02a54;
342	  /* BugReportButton / the feedback page's beta callout — a distinct neon
343	     lime, not mint (already "Popular"/positive elsewhere), pulled darker
344	     here for the same reason every other accent above is: #39ff6a measured
345	     a 1.16:1 contrast ratio against this theme's page background, nowhere
346	     close to the 4.5:1 floor. This shade holds 4.7:1. */
347	  --color-neon-bug: #0d7a30;
348	
349	  /* Inverted ramp — 50 is ink, 950 is paper. */
350	  --color-slate-50: #0a1829;
351	  --color-slate-100: #10243a;
352	  --color-slate-200: #18304a;
353	  --color-slate-300: #26405c;      /* body text */
354	  --color-slate-400: #4a6382;
355	  --color-slate-500: #607a99;
356	  --color-slate-600: #7b91ad;
357	  --color-slate-700: #a9bbd2;
358	  --color-slate-800: #d7e1ee;
359	  --color-slate-900: #e9eff8;
360	  --color-slate-950: #f5f8fc;
361	
362	  --color-tx: #081729;
363	  --color-tx-body: #223449;
364	  --color-tx-mute: #4a6182;
365	  --color-tx-dim: #47607f;
366	  --color-tx-faint: #64778e;
367	
368	  --fg: #0a1829;
369	  --fg-muted: #4a6182;
