371	  /* --color-white IS flipped to ink — second reversal, and this is the one
372	     that stays. Leaving it white made "text-white" (1,640 uses, almost all
373	     plain heading ink) disappear on every now-light card across the app —
374	     worse than the problem it was meant to solve, and the more visible bug.
375	     What actually broke last time was the OPACITY-MODIFIED variants —
376	     `bg-white/5`, `border-white/10`, `text-white/70` — which resolve through
377	     this same token and are calibrated as lighteners on a dark base. Those are
378	     decoupled below via attribute selectors on the literal class text, so they
379	     stop moving with this token at all. That is the fix; flipping the base
380	     value back and forth was chasing the wrong variable. */
381	  --color-white: #0a1829;
