383	  /* The navy ramp is the app's SURFACE ramp — bg-navy-900 (180 uses) and
384	     bg-navy-950 (140) are cards, panels and button faces. Left dark while the
385	     text flipped to ink, they were dark blocks with invisible labels on them.
386	     Inverted like slate: 950 was the darkest ground, so it becomes the
387	     lightest paper. */
388	  --color-navy-950: #ffffff;
389	  --color-navy-900: #fdfeff;
390	  --color-navy-850: #f6f9fd;
391	  --color-navy-800: #eff4fb;
392	  --color-navy-700: #e0e9f5;
393	  --color-navy-600: #d0dcee;
394	}
