737	  background:
738	    linear-gradient(#fff, #fff) padding-box,
739	    conic-gradient(from var(--orbit),
740	      #14c5e4 0deg, #6be6ff 40deg, #2f7eef 100deg,
741	      #8c3ae9 170deg, #d623e1 215deg, #ff8cf2 255deg,
