751	html[data-theme="light"] .card-glass {
752	  background: rgba(255, 255, 255, 0.66);
753	  border-color: color-mix(in srgb, var(--tone) 42%, transparent);
754	  box-shadow: 0 10px 26px rgba(15, 23, 42, 0.12);
755	}
