2152	  /* ── tone chip ───────────────────────────────────────────────────────────
2153	     The role/status pill as the concept screens actually draw it, which is
2154	     NOT what `.badge` above does. Measured off the owner's Team concept: an
2155	     "Admin" pill is a very dark tinted fill (rgb 17,15,64) with a 1px border
2156	     a step brighter (rgb 34,28,97), a FULL-saturation icon (rgb 145,42,247)
2157	     and LIGHT text in the same hue (rgb 190,120,232). `.badge` inverts that —
2158	     a saturated fill with dark text — which is what reads as a loud sticker
2159	     next to the concept's restrained chip.
2160	
2161	     One shape, four tones, driven by --chip-h/--chip-s so a tone is three
2162	     numbers rather than three hand-mixed hexes. The icon inside takes
2163	     `currentColor`; set it apart with .chip-tone-mark. */
2164	  /* Values are the concept's, measured: an Admin chip's fill is rgb(17,15,64)
2165	     = hsl(242 62% 15%), its border rgb(34,28,97) = hsl(245 55% 24%), its text
2166	     rgb(190,120,232) = hsl(277 71% 69%). The fill/border sit a touch cooler
2167	     than the mark and label, which is why --chip-hm exists: tones that need
2168	     it push the mark and text a few degrees off the fill's hue rather than
2169	     rendering the whole chip as one flat colour. */
2170	  .chip-tone {
2171	    --chip-h: 218; --chip-s: 90%; --chip-hm: var(--chip-h);
2172	    display: inline-flex; align-items: center; gap: 7px;
2173	    height: 26px; padding: 0 11px; border-radius: 8px;
2174	    font-size: 11.5px; font-weight: 650; white-space: nowrap;
2175	    color: hsl(var(--chip-hm) calc(var(--chip-s) * 0.78) 72%);
2176	    background: hsl(var(--chip-h) calc(var(--chip-s) * 0.66) 14%);
2177	    border: 1px solid hsl(var(--chip-h) calc(var(--chip-s) * 0.48) 25%);
2178	    box-shadow: 0 0 14px -9px hsl(var(--chip-hm) var(--chip-s) 55% / 0.65);
2179	  }
2180	  /* The mark reads at full saturation while the label stays light — the
2181	     two-tone split is most of why the concept's chips look considered. */
2182	  .chip-tone .chip-tone-mark { color: hsl(var(--chip-hm) var(--chip-s) 60%); flex: none; }
2183	  .chip-amber  { --chip-h: 38;  --chip-s: 88%; --chip-hm: 43; }
2184	  .chip-violet { --chip-h: 244; --chip-s: 84%; --chip-hm: 273; }
2185	  .chip-mint   { --chip-h: 160; --chip-s: 78%; --chip-hm: 156; }
2186	  .chip-blue   { --chip-h: 213; --chip-s: 88%; --chip-hm: 205; }
2187	  .chip-slate  { --chip-h: 216; --chip-s: 22%; }
2188	  .chip-rose   { --chip-h: 346; --chip-s: 78%; }
