2190	  /* ── icon tone + glow ────────────────────────────────────────────────────
2191	     The vector set (lib/nx/icon-paths.ts) draws in `currentColor`, so colour
2192	     and bloom live here rather than in the artwork. Each mark carries a tone
2193	     class from NX_ICON_TONE — sampled off the original sprite sheet, so an
2194	     icon keeps the colour the art already gave it.
2195	
2196	     `drop-shadow` uses `currentColor`, so ONE glow rule serves every tone and
2197	     any override automatically re-tints its own bloom. Two stops: a tight
2198	     core and a wider halo, which is what reads as neon rather than as a
2199	     blurry shadow. */
2200	  .nx-ico {
2201	    filter:
2202	      drop-shadow(0 0 2px color-mix(in srgb, currentColor 55%, transparent))
2203	      drop-shadow(0 0 6px color-mix(in srgb, currentColor 32%, transparent));
2204	  }
2205	  .nx-ico-rose   { color: var(--color-rose); }
2206	  .nx-ico-amber  { color: var(--color-amber); }
