2312	  /* ── liquid glass ─────────────────────────────────────────────────────
2313	     Built from scratch against the concept, in the iOS-26 idiom: the material
2314	     is mostly the BLUR, not a fill. Three things sell it — a gradient hairline
2315	     that reads as a lens edge (bright where light lands, near-gone in shadow),
2316	     a specular gloss falling off across the top third, and a slow highlight
2317	     travelling across the surface. Everything else is restraint. */
2318	  .glass {
2319	    position: relative; isolation: isolate;
2320	    border-radius: 26px;
2321	    background: linear-gradient(168deg, rgba(150,190,255,0.065), rgba(90,110,215,0.03) 58%, rgba(12,22,54,0.09));
2322	    -webkit-backdrop-filter: blur(24px) saturate(205%) brightness(1.05);
2323	    backdrop-filter: blur(24px) saturate(205%) brightness(1.05);
2324	    box-shadow:
2325	      inset 0 1.5px 0 rgba(210,245,255,0.95),         /* the lit top edge */
2326	      inset 0 -1px 0 rgba(255,255,255,0.14),         /* light caught underneath */
2327	      inset 0 18px 32px -20px rgba(255,255,255,0.72),/* gloss falling into the body */
2328	      inset 0 -30px 44px -32px rgba(0,0,0,0.5),       /* weight at the bottom */
2329	      0 14px 42px -14px rgba(0,0,0,0.72);            /* it floats above the art */
2330	  }
2331	  /* the lens edge: a hairline that is bright top-left and all but gone bottom-right */
2332	  .glass::before {
2333	    content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1px;
2334	    background: linear-gradient(148deg,
2335	      rgba(255,255,255,0.80) 0%, rgba(255,255,255,0.22) 26%,
2336	      rgba(255,255,255,0.05) 56%, rgba(255,255,255,0.34) 100%);
2337	    -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
2338	    -webkit-mask-composite: xor; mask-composite: exclude;
2339	    pointer-events: none; z-index: 2;
2340	  }
2341	  /* the gloss, plus a highlight that drifts across it */
