2608	  /* ── App-frame routes ──────────────────────────────────────────────────
2609	     The mail client is an application, not a document: its rail, list and
2610	     reading pane scroll independently, so the WINDOW must not scroll at all.
2611	     `flex-1` cannot express that — the shell's column is `min-h-dvh`, so a
2612	     flex child only ever grows the page. This hands the surface the exact
2613	     height that is left over instead.
2614	
2615	     Subtracted, in order: the sticky header (64px, 72px from lg), the fixed
2616	     mobile tab bar (68px, gone from lg), and --nx-chrome for anything sitting
2617	     ABOVE the shell in normal flow. That last one is the sandbox banner, which
2618	     does not exist in production — hardcoding its height would leave every
2619	     production app page one banner short of the viewport. */
2620	  /* Declared directly (not nested as `:root { … }`) because this whole
2621	     section already sits inside `:root:has(.nx-shell-root) { … }` — nesting
2622	     a bare `:root` selector one level deeper would compile to
2623	     `:root:has(.nx-shell-root) :root`, which can never match (`:root` cannot
2624	     be its own descendant) and silently dropped this fallback, leaving
2625	     --nx-chrome undefined on any portal page without an active banner. */
2626	  --nx-chrome: 0px;
2627	  body.nx-has-banner { --nx-chrome: 28px; }
2628	
2629	  /* The shell and its sidebar are sized against the viewport, but they do not
2630	     START at the top of it when something sits above them in flow. A bare
2631	     `min-h-dvh`/`h-dvh` then makes the document exactly --nx-chrome taller than
2632	     the window — the app frame can fit its own content perfectly and the page
2633	     still scrolls by the height of the banner. */
2634	  .nx-shell-root { min-height: calc(100dvh - var(--nx-chrome)); }
2635	  .nx-shell-rail { height: calc(100dvh - var(--nx-chrome)); }
