2	import { NX_ICONS, NX_ICON_TONE, type NxTone } from "@/lib/nx/icon-paths";
3	
4	/* ── one dial for icon size, site-wide ────────────────────────────────────
5	   Every mark in the system is drawn a fixed multiple of the size its call site
6	   asks for. Applying it HERE rather than editing hundreds of call sites keeps
7	   the relative sizing intact: an icon that was deliberately smaller than its
8	   neighbour stays proportionally smaller, it is just bigger in absolute terms.
9	   Change this one number to retune the whole set.
10	
11	   Note for anyone adding a primitive: scale exactly ONCE per rendered mark.
12	   `Plate` draws an `Icon` inside itself, so it scales its own BOX and passes
13	   the raw size through — scaling in both places would compound to 2.25x. */
14	export const ICON_SCALE = 1.5;
15	export const iconPx = (n: number) => Math.round(n * ICON_SCALE);
16	
17	/**
18	 * One interface mark.
19	 *
20	 * VECTOR FIRST, sprite as the fallback. `lib/nx/icon-paths.ts` carries the set
21	 * redrawn as 24x24 paths; anything it defines renders as an inline SVG in
22	 * `currentColor`, and anything it doesn't — the sheet's brand row (linux,
23	 * docker, postgres…) and the five 3D product renders — still comes off
24	 * `public/nx/nxicons.webp` exactly as before.
25	 *
26	 * Why the switch is here rather than at 137 call sites: the sprite's marks are
27	 * pre-coloured, so one inside a tinted control renders in the SHEET's colour
28	 * instead of the control's (a teal shieldcheck on a violet "Admin" chip is the
29	 * bug that started this). Routing both through one component means every call
30	 * site gets `currentColor` without being edited, and a name with no vector yet
31	 * silently keeps working.
32	 *
33	 * `size` still means what it always did — ICON_SCALE is applied here for BOTH
34	 * paths, so a swap is 1:1 and `Plate` (which sizes its box with `iconPx`)
35	 * needs no change.
36	 */
37	export function Icon({
38	  name, size = 20, className = "", style, strokeWidth = 1.8, tone,
39	}: {
40	  name: string; size?: number; className?: string; style?: React.CSSProperties;
41	  /** Outline weight for vector marks. Ignored by filled marks and the sprite. */
42	  strokeWidth?: number;
43	  /**
44	   * Override the mark's own tone. `"inherit"` hands the colour back to the
45	   * surrounding text, which is what a mark inside a tinted chip or a solid
46	   * button needs — though both of those are already handled centrally in
47	   * globals.css, so passing this is rare.
48	   */
49	  tone?: NxTone | "inherit";
50	}) {
51	  const s = iconPx(size);
52	  const vector = NX_ICONS[name];
53	
54	  if (vector) {
55	    /* The tone rides as a CLASS, never an inline style. Inline colour would
56	       beat every context rule, and context has to be able to win: a mark in
