120	export default async function RootLayout({ children }: { children: React.ReactNode }) {
121	  // Admin-configured live-chat snippet (trusted input — only staff can set it).
122	  let chatSnippet = "";
123	  try {
124	    const { getSetting } = await import("@/lib/settings");
125	    chatSnippet = (await getSetting("livechat_snippet", "")) ?? "";
126	  } catch {
127	    /* settings unavailable — chat stays off */
128	  }
129	
130	  // Signed-in viewer (if any) so the chat widget prefills name/email and doesn't
131	  // re-ask; anonymous visitors are required to provide them. Best-effort.
132	  let chatViewer: { name: string | null; email: string | null } | null = null;
133	  try {
134	    const { currentUser } = await import("@/lib/auth");
135	    const u = await currentUser();
136	    if (u) chatViewer = { name: u.name ?? null, email: u.email ?? null };
137	  } catch {
138	    /* not signed in / auth unavailable — widget will ask for details */
139	  }
140	  return (
141	    // `nx-has-banner` publishes the sandbox banner's height as --nx-chrome.
142	    // Full-height "app frame" routes (the mail client) size themselves to the
143	    // viewport minus the fixed chrome above them, and this banner is real
144	    // chrome here that does not exist in production — without it the mail page
145	    // would be exactly one banner too tall and scroll in the sandbox only.
146	    <html lang="en" className={`${nxSans.variable} ${nxMono.variable}`} suppressHydrationWarning>
147	      <head>
148	        {/* Applies the saved theme BEFORE first paint. A React effect runs after
149	            hydration, which is one paint too late — every load would flash the
150	            dark theme at anyone who chose light. Deliberately tiny, deliberately
151	            blocking, and it fails closed to dark.
152	
153	            Gated to /dashboard: `nx-theme` lives in localStorage, which is
154	            shared by the WHOLE origin, not just the portal — the toggle only
155	            renders inside the dashboard shell, but without this check, a
156	            customer who ever switched to light mode there got the marketing
157	            site (and login, and a client-side nav back from the dashboard)
158	            rendered light too, since this script has no other way to know
159	            which surface it is painting. Marketing/login never had a light
160	            theme built for them; they must always fail closed to dark. */}
161	        <script
162	          dangerouslySetInnerHTML={{
163	            __html:
164	              "try{if(location.pathname.startsWith('/dashboard')&&localStorage.getItem('nx-theme')==='light')" +
165	              "document.documentElement.setAttribute('data-theme','light')}catch(e){}",
166	          }}
167	        />
168	      </head>
169	      <body className={SANDBOX ? "nx-has-banner" : undefined}>
170	        <SandboxBanner />
171	        {children}
172	        <CookieConsent />
173	        <LiveChat snippet={chatSnippet} />
174	        <ChatWidget viewer={chatViewer} />
175	        <OrganizationJsonLd />
176	        <Analytics />
177	        <TrackingProvider />
178	        <MetaPixelTracker />
179	      </body>
180	    </html>
181	  );
182	}
