1	"use client";
2	
3	import { useEffect, useRef } from "react";
4	import { isLightTheme } from "./auroraTheme";
5	
6	/* Page-level aurora.
7	 *
8	 * The reference screens carry a large, moving light field across the top-right
9	 * of every page — the earlier SVG ribbon was a 210px decoration inside one
10	 * header, which is why it read as absent. This is the real thing: layered
11	 * ribbons drifting on a canvas, capped at 30fps, paused when the tab is hidden
12	 * or the user asks for reduced motion.
13	 *
14	 * Dark mode composites these strokes with `globalCompositeOperation =
15	 * "lighter"`, which only ever ADDS light — correct over the near-black page
16	 * this was built for, but on a light page it just pushes every pixel toward
17	 * white (the flat grey wash bug also fixed in StreamsBg/the per-page Aurora
18	 * components; see auroraTheme.ts for the fuller explanation). Light mode here
19	 * switches to normal "source-over" blending and a second, darker hex palette
20	 * instead — this file predates the shared hsla-gradient helper (its stops are
21	 * a fixed 4-colour ramp, not a hue pair), so the fix is a parallel palette
22	 * rather than a call into auroraStrandGradient.
23	 */
24	export function AuroraBg() {
25	  const ref = useRef<HTMLCanvasElement>(null);
26	
27	  useEffect(() => {
28	    const cv = ref.current;
29	    if (!cv) return;
30	    const g = cv.getContext("2d");
31	    if (!g) return;
32	
33	    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
34	    let raf = 0, last = 0, W = 0, H = 0;
35	    const dpr = Math.min(2, window.devicePixelRatio || 1);
36	
37	    const RIBBONS = [
38	      { y: 0.20, amp: 62, frq: 0.0016, spd: 0.16, th: 108, hue: 0.00, op: 0.15 },
39	      { y: 0.34, amp: 84, frq: 0.0012, spd: -0.11, th: 142, hue: 0.42, op: 0.11 },
40	      { y: 0.12, amp: 44, frq: 0.0023, spd: 0.24, th: 74,  hue: 0.72, op: 0.08 },
41	    ];
42	
43	    function size() {
44	      const r = cv!.getBoundingClientRect();
45	      W = Math.max(1, r.width); H = Math.max(1, r.height);
46	      cv!.width = Math.round(W * dpr); cv!.height = Math.round(H * dpr);
47	      g!.setTransform(dpr, 0, 0, dpr, 0, 0);
48	    }
49	
50	    /* Dark: the original bright ramp, meant to bloom additively.
51	       Light: the same four hues pulled down to ~35-40% lightness (from a
52	       ~45-50% starting point — this ramp never sat as pale as the hsla
53	       aurora's 62-80%, so it needed a smaller drop) so they read as
54	       saturated colour once painted normally instead of only brightening. */
55	    const RAMP_DARK = ["#14c5e4", "#2f7eef", "#6f37d6", "#d623e1"];
56	    const RAMP_LIGHT = ["#0a7a91", "#1a4fb0", "#5220a0", "#a01aa8"];
57	
58	    function stop(x0: number, x1: number, hue: number, a: number, isLight: boolean) {
59	      const lg = g!.createLinearGradient(x0, 0, x1, 0);
60	      const A = isLight ? RAMP_LIGHT : RAMP_DARK;
61	      const i = Math.min(2, Math.floor(hue * 3));
62	      /* Normal blending does not stack brightness across overlapping
63	         strokes the way "lighter" does, so light mode gets more alpha. */
64	      const av = isLight ? Math.min(1, a * 2.2) : a;
65	      lg.addColorStop(0, "rgba(0,0,0,0)");
66	      lg.addColorStop(0.28, A[i] + Math.round(av * 190).toString(16).padStart(2, "0"));
67	      lg.addColorStop(0.62, A[i + 1] + Math.round(av * 255).toString(16).padStart(2, "0"));
68	      lg.addColorStop(1, "rgba(0,0,0,0)");
69	      return lg;
70	    }
71	
72	    function frame(now: number) {
73	      raf = requestAnimationFrame(frame);
74	      if (document.hidden) return;
75	      if (now - last < 1000 / 30) return;
76	      last = now;
77	      const t = now / 1000;
78	      const isLight = isLightTheme();
79	      g!.clearRect(0, 0, W, H);
80	      g!.globalCompositeOperation = isLight ? "source-over" : "lighter";
81	      for (const r of RIBBONS) {
82	        g!.beginPath();
83	        for (let x = -40; x <= W + 40; x += 10) {
84	          const y = r.y * H
85	            + Math.sin(x * r.frq + t * r.spd) * r.amp
86	            + Math.sin(x * r.frq * 2.6 + t * r.spd * 1.7) * r.amp * 0.34;
87	          x === -40 ? g!.moveTo(x, y) : g!.lineTo(x, y);
88	        }
89	        g!.strokeStyle = stop(0, W, r.hue, r.op, isLight);
90	        g!.lineWidth = r.th;
91	        g!.lineCap = "round";
92	        g!.filter = "blur(30px)";
93	        g!.stroke();
94	        g!.filter = "blur(6px)";
95	        g!.lineWidth = r.th * 0.16;
96	        g!.strokeStyle = stop(0, W, r.hue, r.op * 0.9, isLight);
97	        g!.stroke();
98	        g!.filter = "none";
99	      }
100	      g!.globalCompositeOperation = "source-over";
101	    }
102	
103	    size();
104	    const ro = new ResizeObserver(size);
105	    ro.observe(cv);
106	    if (reduce) { frame(0); cancelAnimationFrame(raf); raf = 0; }
107	    else raf = requestAnimationFrame(frame);
108	    return () => { if (raf) cancelAnimationFrame(raf); ro.disconnect(); };
109	  }, []);
110	
111	  return (
112	    <div aria-hidden className="pointer-events-none fixed inset-x-0 top-0 z-0 h-[560px] overflow-hidden">
113	      <canvas ref={ref} className="h-full w-full opacity-70" />
114	      {/* fade it into the page so it never fights the cards */}
115	      <div className="absolute inset-0"
116	           style={{ background: "linear-gradient(180deg, transparent 30%, color-mix(in srgb, var(--color-bg) 68%, transparent) 70%, var(--color-bg) 100%)" }} />
117	    </div>
118	  );
119	}
