11	const GAMES: Record<string, { sky: [string, string]; glow: string; ridge: string; fore: string; scene: Scene }> = {
12	  Palworld:        { sky: ["#7fd4ff", "#2a6fc0"], glow: "#ffd47a", ridge: "#2d5a92", fore: "#16345c", scene: "peaks" },
13	  Minecraft:       { sky: ["#79c7f2", "#2f7fb8"], glow: "#bff08a", ridge: "#3f8f4a", fore: "#255c30", scene: "forest" },
14	  Rust:            { sky: ["#e0975a", "#7a3d22"], glow: "#ffb066", ridge: "#5a2c19", fore: "#331709", scene: "ruins" },
15	  "ARK: Survival": { sky: ["#7b5fd4", "#22706c"], glow: "#5fe0d0", ridge: "#1c4d55", fore: "#0e2a33", scene: "peaks" },
16	  FiveM:           { sky: ["#a04fe0", "#3a1a6a"], glow: "#ff6eb8", ridge: "#2a1150", fore: "#160829", scene: "city" },
17	  Valheim:         { sky: ["#d4703a", "#2a3a52"], glow: "#ffb066", ridge: "#1e2c3e", fore: "#111a26", scene: "forest" },
18	  "Counter-Strike 2": { sky: ["#e0983a", "#2a4a6a"], glow: "#ffd07a", ridge: "#1e3550", fore: "#101f30", scene: "city" },
19	  "Team Fortress 2":  { sky: ["#d9784a", "#8a5a30"], glow: "#ffc98a", ridge: "#5e3a1e", fore: "#38210f", scene: "industry" },
