21	  "7 Days to Die": { sky: ["#c0453a", "#2a1410"], glow: "#ff8a5a", ridge: "#20100c", fore: "#120806", scene: "ruins" },
22	  Terraria:        { sky: ["#6fd46f", "#3f9fd4"], glow: "#fff0a0", ridge: "#2a7a4a", fore: "#17512f", scene: "forest" },
23	  "Project Zomboid": { sky: ["#8a9a6a", "#3a4230"], glow: "#d8e0a0", ridge: "#2b3324", fore: "#181d14", scene: "ruins" },
24	  Enshrouded:      { sky: ["#4fc0b0", "#5a3f90"], glow: "#a0ffe8", ridge: "#2a2f5e", fore: "#161834", scene: "cave" },
25	  Satisfactory:    { sky: ["#e08a3a", "#2f4457"], glow: "#ffcf7a", ridge: "#233544", fore: "#131f29", scene: "industry" },
26	  Factorio:        { sky: ["#d07a30", "#4a3524"], glow: "#ffc070", ridge: "#382719", fore: "#20160e", scene: "industry" },
27	  DayZ:            { sky: ["#8a9a7a", "#2f3a2a"], glow: "#cfe0b0", ridge: "#243020", fore: "#141a12", scene: "forest" },
28	  "V Rising":      { sky: ["#c02a5a", "#26081c"], glow: "#ff6a9a", ridge: "#1e0616", fore: "#12040e", scene: "cave" },
