32	const FALLBACK = GAMES.Palworld;
33	
34	function ridge(scene: Scene, y: number, seed: number) {
35	  const r = (n: number) => { const x = Math.sin(seed * 97.13 + n * 41.7) * 43758.5453; return x - Math.floor(x); };
36	  const pts: string[] = [`M0 100`, `L0 ${y}`];
37	  if (scene === "city" || scene === "industry") {
38	    let x = 0, i = 0;
39	    while (x < 100) {
40	      const w = 5 + r(i) * 9, h = y - (4 + r(i + 50) * 26);
41	      pts.push(`L${x.toFixed(1)} ${h.toFixed(1)}`, `L${(x + w).toFixed(1)} ${h.toFixed(1)}`);
42	      x += w; i++;
43	    }
44	    pts.push(`L100 ${y}`);
45	  } else if (scene === "forest") {
46	    let x = 0, i = 0;
47	    while (x < 104) {
48	      const w = 6 + r(i) * 5, h = y - (8 + r(i + 30) * 20);
49	      pts.push(`L${x.toFixed(1)} ${y.toFixed(1)}`, `L${(x + w / 2).toFixed(1)} ${h.toFixed(1)}`, `L${(x + w).toFixed(1)} ${y.toFixed(1)}`);
50	      x += w * 0.86; i++;
51	    }
52	  } else {
53	    let x = 0, i = 0;
54	    while (x < 108) {
55	      const w = 14 + r(i) * 16, h = y - (10 + r(i + 70) * 30);
56	      pts.push(`L${(x + w / 2).toFixed(1)} ${h.toFixed(1)}`, `L${(x + w).toFixed(1)} ${y.toFixed(1)}`);
57	      x += w * 0.78; i++;
58	    }
59	  }
60	  pts.push("L100 100 Z");
61	  return pts.join(" ");
62	}
