68	  return (
69	    <svg className={className} viewBox="0 0 100 100" preserveAspectRatio="xMidYMid slice" aria-hidden>
70	      <defs>
71	        <linearGradient id={`sky${id}`} x1="0" y1="0" x2="0.3" y2="1">
