79	          <stop offset="0.30" stopColor="#000" stopOpacity="0" />
80	          <stop offset="1" stopColor="#00060f" stopOpacity="0.92" />
81	        </linearGradient>
82	      </defs>
83	      <rect width="100" height="100" fill={`url(#sky${id})`} />
84	      <circle cx="68" cy="26" r="46" fill={`url(#sun${id})`} />
85	      <circle cx="68" cy="26" r="6" fill={g.glow} opacity="0.95" />
