88	      <path d={ridge(g.scene, 54, seed + 31)} fill={g.ridge} opacity="0.42" />
89	      <rect y="40" width="100" height="34" fill={g.sky[1]} opacity="0.30" />
90	      <path d={ridge(g.scene, 66, seed)} fill={g.ridge} opacity="0.92" />
91	      <rect y="56" width="100" height="30" fill={g.fore} opacity="0.22" />
92	      <path d={ridge(g.scene, 82, seed + 11)} fill={g.fore} />
93	      <rect width="100" height="100" fill={`url(#vig${id})`} />
94	    </svg>
95	  );
96	}
