"use client";

/* The region globe — rebuilt from scratch on plain Canvas 2D.
 *
 * WHY NOT COBE. The previous version was built on `cobe`, which draws a
 * dot-textured sphere plus markers and arcs and nothing else. The concepts on
 * the Region Selector card want three things cobe has no way to draw: a
 * lat/lon graticule wrapping the sphere, city-to-city links with packets
 * visibly riding them, and a bright brand-ramp limb. Every attempt to get
 * there through cobe's handful of scalar options (mapBrightness, glowColor,
 * diffuse) was a fight with a renderer that had already decided how it looks.
 * So this owns its own projection and draws each layer directly.
 *
 * WHAT IS REAL AND WHAT IS DECORATION. The region markers are the real
 * deployable regions passed in from lib/nx/catalog — same coordinates the
 * wizard orders against. The land and the city positions are real geography
 * out of public/nx/globe-geo.json (`cities` is [lon, lat, weight] triples).
 * The LINKS between cities, and the packets riding them, are decoration: they
 * are not measured traffic, not real routes, and no figure anywhere on this
 * canvas is presented as a measurement. Keep it that way — the moment this
 * draws a number, that number has to come from somewhere real.
 *
 * Projection is orthographic: lat/lon to a unit vector, rotate by phi (spin)
 * and theta (tilt), then drop z. Positive z is the hemisphere facing the
 * viewer, which is what every layer tests to decide visibility and depth fade.
 */

import { useEffect, useMemo, useRef } from "react";
import type { Region } from "@/lib/nx/catalog";

type Vec3 = [number, number, number];
type Geo = { fill: number[][]; cities: number[] };

const DEG = Math.PI / 180;

/* Brand ramp, straight off the logo: #3fbcd8 -> #4f7cff -> #d623e1. */
const RAMP: Vec3[] = [
  [63, 188, 216],
  [79, 124, 255],
  [214, 35, 225],
];

function ramp(t: number): Vec3 {
  const u = Math.max(0, Math.min(1, t));
  const seg = u <= 0.5 ? 0 : 1;
  const k = u <= 0.5 ? u * 2 : (u - 0.5) * 2;
  const a = RAMP[seg];
  const b = RAMP[seg + 1];
  return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k];
}

const rgba = ([r, g, b]: Vec3, a: number) =>
  `rgba(${Math.round(r)},${Math.round(g)},${Math.round(b)},${a})`;

