/* The hero: a server rack with aurora light streams wrapping around it.
 *
 * Two things make this read like the concept. First, the streams are BUNDLES OF
 * THIN FILAMENTS, not broad bands — six or seven strands running roughly
 * parallel, each with a hairline core and a wide soft halo, fanning apart and
 * gathering along the path. A single wide band reads as a painted blade; a
 * bundle reads as light in motion.
 *
 * Second, the wrap needs two canvases with the rack between them and one shared
 * clock: a bundle dives behind the stack and the same bundle reappears on the
 * front layer lower down. A single layer, at any z-index, can only ever be in
 * front of the rack or behind it.
 */

type Pt = [number, number];
type Stream = {
  p: [Pt, Pt, Pt, Pt];   // the bundle's centreline
  n: number;             // how many filaments
  spread: number;        // how far they fan apart, as a fraction of the box
  from: string; to: string;   // colour across the bundle, cyan -> magenta
  spd: number; amp: number;   // how the centreline breathes
  core: number; glow: number; // filament weight and halo weight
  body: number;               // the soft atmospheric stroke the threads sit in
  alpha: number;
};

